  "file_path": "/workspace/work/tune.py",
  "content": """"Tune per-item weights per domain to maximize domain macro Pearson (coarse, robust).
Uses sweep per-item scores. Strategy:
 - ideal direction per domain = sum of z-scored visible target vectors
 - keep items whose score profile positively correlates with ideal; drop anti-correlated;
   optionally up-weight strong anchors.
Reports equal-weight vs tuned objective.
"""
import json, math, itertools, sys
from analyze import LABELS, MODELS, pearson, spearman

QUESTIONS = json.load(open('/workspace/submission/assets/questions.json'))
QD = {q['id']: q['domain'] for q in QUESTIONS}
DOMAINS = ['coding', 'co-work', 'reasoning']


def zscore(v):
    m = sum(v) / len(v)
    s = math.sqrt(sum((x - m) ** 2 for x in v) / len(v)) or 1.0
    return [(x - m) / s for x in v]


def ideal_direction(dom):
    """Sum of z-scored target vectors across MODELS (missing models -> 0 contribution)."""
    acc = {m: 0.0 for m in MODELS}
    for tname, t in LABELS.items():
        if t['domain'] != dom:
            continue
        common = [m for m in t['scores']]
        zs = zscore([t['scores'][m] for m in common])
        for m, z in zip(common, zs):
            acc[m] += z
    return acc


def load_sweep(paths):
    """Return item_scores: {item_id: {model: score}}"""
    item_scores = {}
    for p in paths:
        data = json.load(open(p))
        model = data['model']
        for it in data['items']:
            if it.get('score') is not None:
                item_scores.setdefault(it['id'], {})[model] = it['score']
    return item_scores


def domain_agg(item_scores, weights, dom):
    out = {}
    for m in MODELS:
        num = den = 0.0
        for iid, w in weights.items():
            if QD[iid] == dom and m in item_scores.get(iid, {}):
                num += w * item_scores[iid][m]; den += w
        out[m] = num / den if den else None
    return out


def macro_objective(agg_by_domain):
    per_dom = {}
    for dom in DOMAINS:
        ps = []
        for tname, t in LABELS.items():
            if t['domain'] != dom:
                continue
            common = [m for m in t['scores'] if agg_by_domain[dom].get(m) is not None]
            xs = [agg_by_domain[dom][m] for m in common]
            ys = [t['scores'][m] for m in common]
            p = pearson(xs, ys)
            if p is not None:
                ps.append(p)
        per_dom[dom] = sum(ps) / len(ps) if ps else None
    valid = [v for v in per_dom.values() if v is not None]
    return per_dom, (sum(valid) / len(valid) if valid else None)


def main(paths):
    item_scores = load_sweep(paths)
    # report per-item model score matrix
    for dom in DOMAINS:
        print(f"\n=== {dom} ===")
        ideal = ideal_direction(dom)
        print("ideal direction:", {m: round(v, 2) for m, v in ideal.items()})
        for iid in [q['id'] for q in QUESTIONS if QD[q['id']] == dom]:
            sc = item_scores.get(iid, {})
            row = {m: sc.get(m) for m in MODELS}
            vals = [row[m] for m in MODELS if row[m] is not None]
            spread = (max(vals) - min(vals)) if vals else 0
            print(f"  {iid:14s} " + " ".join(f"{('NA' if row[m] is None else f'{row[m]:.2f}'):>5}" for m in MODELS) + f"  spread={spread:.2f}")

    # equal weight objective
    eq_weights = {q['id']: 1.0 for q in QUESTIONS}
    agg = {d: domain_agg(item_scores, eq_weights, d) for d in DOMAINS}
    per_dom, obj = macro_objective(agg)
    print("\n=== EQUAL WEIGHTS ===")
    for d in DOMAINS:
        print(f"  {d}: macro={per_dom[d]}")
    print(f"  OBJECTIVE={obj}")

    # tuned weights: keep items positively correlated with ideal direction
    tuned = {}
    for dom in DOMAINS:
        ideal = ideal_direction(dom)
        im = [ideal[m] for m in MODELS]
        for q in QUESTIONS:
            iid = q['id']
            if QD[iid] != dom:
                tuned[iid] = 1.0
                continue
            sc = item_scores.get(iid, {})
            common = [m for m in MODELS if m in sc]
            if len(common) < 3:
                tuned[iid] = 1.0; continue
            xs = [sc[m] for m in common]
            ys = [ideal[m] for m in common]
            p = pearson(xs, ys)
            # variance check
            spread = max(xs) - min(xs)
            if spread < 1e-9:
                tuned[iid] = 0.0      # constant item: no utility
            elif p is not None and p > 0.2:
                tuned[iid] = 1.0
            elif p is not None and p < -0.2:
                tuned[iid] = 0.0      # anti-correlated: drop
            else:
                tuned[iid] = 0.5      # weak/noisy: down-weight
    agg2 = {d: domain_agg(item_scores, tuned, d) for d in DOMAINS}
    per_dom2, obj2 = macro_objective(agg2)
    print("\n=== TUNED WEIGHTS ===")
    for d in DOMAINS:
        kept = sum(1 for q in QUESTIONS if QD[q['id']] == d and tuned[q['id']] > 0)
        print(f"  {d}: macro={per_dom2[d]}  kept_items={kept}")
    print(f"  OBJECTIVE={obj2}")
    print("\ntuned_weights =", json.dumps(tuned))


if __name__ == '__main__':
    main(sys.argv[1:])
"
}

